// Des: Unit tests for the fresh environment merge
// Flo: feed fixed pairs and maps > assert exact PATH text, values, diff names > read a real test key if present
// I/O: Pair lists + env maps > pass or fail
// ===================================================================
const std = @import("std"); const builtin = @import("builtin"); const fres = @import("st-envi-fres.zig");
const tszz = std.testing; const Map = fres.Map; const Pair = fres.Pair; const S: u8 = if (builtin.os.tag == .windows) ';' else ':';
fn joiz(allo: std.mem.Allocator, parts: []const []const u8) ![]u8 { var outz: std.ArrayList(u8) = .empty; for (parts, 0..) |part, indx| { if (indx > 0) try outz.append(allo, S); try outz.appendSlice(allo, part); } return outz.toOwnedSlice(allo); }
test "pathMerg keeps lead order, then adds only the new session entries" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const lead = try joiz(allo, &.{ "/a", "/b" }); const proc = try joiz(allo, &.{ "/b", "/x" }); const resu = try fres.pathMerg(allo, &.{ lead, "/c" }, proc); try tszz.expectEqualStrings(try joiz(allo, &.{ "/a", "/b", "/c", "/x" }), resu); }
test "pathMerg drops empty entries and repeats" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const lead = try joiz(allo, &.{ "/a", "", "/a", " ", "/b" }); const resu = try fres.pathMerg(allo, &.{lead}, ""); try tszz.expectEqualStrings(try joiz(allo, &.{ "/a", "/b" }), resu); }
test "pathMerg treats a trailing slash as the same entry" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const resu = try fres.pathMerg(allo, &.{"/a/"}, "/a"); try tszz.expectEqualStrings("/a/", resu); }
test "pathMerg with nothing gives an empty text" { const resu = try fres.pathMerg(tszz.allocator, &.{ "", "" }, ""); defer tszz.allocator.free(resu); try tszz.expectEqual(@as(usize, 0), resu.len); }
test "pathMerg is case-blind on Windows only" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); const resu = try fres.pathMerg(allo, &.{"/Aa"}, "/aa"); if (builtin.os.tag == .windows) try tszz.expectEqualStrings("/Aa", resu) else try tszz.expectEqualStrings(try joiz(allo, &.{ "/Aa", "/aa" }), resu); }
test "expaText fills known names and keeps unknown ones as written" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("FOO", "bar"); const resu = try fres.expaText(allo, "%FOO%-%NOPE%-%FOO%", &mapz); try tszz.expectEqualStrings("bar-%NOPE%-bar", resu); }
test "expaText leaves a lone percent, an empty name and plain text alone" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("FOO", "bar"); try tszz.expectEqualStrings("100%", try fres.expaText(allo, "100%", &mapz)); try tszz.expectEqualStrings("a%%b", try fres.expaText(allo, "a%%b", &mapz)); try tszz.expectEqualStrings("plain", try fres.expaText(allo, "plain", &mapz)); try tszz.expectEqualStrings("", try fres.expaText(allo, "", &mapz)); }
test "mergApply: user over machine, REG_SZ stays literal, REG_EXPAND_SZ expands, PATH is joined" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("SystemRoot", "/win"); const old_path = try joiz(allo, &.{ "/old", "/sess" }); try mapz.put("PATH", old_path); const mach = [_]Pair{ .{ .name = "PATH", .valu = "%SystemRoot%/sys;/m2", .expa = true }, .{ .name = "FOO", .valu = "1" }, .{ .name = "LIT", .valu = "100%SystemRoot%" } }; const user = [_]Pair{ .{ .name = "Path", .valu = "/u1" }, .{ .name = "FOO", .valu = "2" }, .{ .name = "BAR", .valu = "%FOO%/x", .expa = true } }; try fres.mergApply(allo, &mapz, &mach, &user, &.{}); try tszz.expectEqualStrings("2", mapz.get("FOO").?); try tszz.expectEqualStrings("2/x", mapz.get("BAR").?); try tszz.expectEqualStrings("100%SystemRoot%", mapz.get("LIT").?); if (builtin.os.tag == .windows) try tszz.expectEqualStrings("/win/sys;/m2;/u1;/old;/sess", mapz.get("PATH").?); }
test "mergApply with no registry data changes nothing" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("PATH", "/keep"); try mapz.put("FOO", "1"); try fres.mergApply(allo, &mapz, &.{}, &.{}, &.{}); try tszz.expectEqualStrings("/keep", mapz.get("PATH").?); try tszz.expectEqualStrings("1", mapz.get("FOO").?); try tszz.expectEqual(@as(usize, 2), mapz.count()); }
test "mergApply keeps process-only names and names the registry does not have" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("ONLY_HERE", "keep"); const user = [_]Pair{.{ .name = "NEW_ONE", .valu = "v" }}; try fres.mergApply(allo, &mapz, &.{}, &user, &.{}); try tszz.expectEqualStrings("keep", mapz.get("ONLY_HERE").?); try tszz.expectEqualStrings("v", mapz.get("NEW_ONE").?); }
test "mergApply skips an empty name" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); const user = [_]Pair{.{ .name = "", .valu = "v" }}; try fres.mergApply(allo, &mapz, &.{}, &user, &.{}); try tszz.expectEqual(@as(usize, 0), mapz.count()); }
test "diffNames lists changed and new names, never unchanged ones" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var base: Map = .init(allo); try base.put("A", "1"); try base.put("B", "2"); var fresh: Map = .init(allo); try fresh.put("A", "1"); try fresh.put("B", "3"); try fresh.put("C", "4"); const names = try fres.diffNames(allo, &base, &fresh); try tszz.expectEqual(@as(usize, 2), names.len); var got_b = false; var got_c = false; for (names) |name| { if (std.mem.eql(u8, name, "B")) got_b = true; if (std.mem.eql(u8, name, "C")) got_c = true; } try tszz.expect(got_b and got_c); }
test "diffNames of equal maps is empty" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var base: Map = .init(allo); try base.put("A", "1"); const names = try fres.diffNames(allo, &base, &base); try tszz.expectEqual(@as(usize, 0), names.len); }
test "applyFres never breaks the map and keeps PATH non-empty" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("PATH", "/keep"); try mapz.put("ONLY_HERE", "x"); fres.applyFres(allo, &mapz); try tszz.expect(mapz.get("PATH").?.len > 0); try tszz.expectEqualStrings("x", mapz.get("ONLY_HERE").?); if (builtin.os.tag != .windows) try tszz.expectEqualStrings("/keep", mapz.get("PATH").?); }
test "applyFres on this machine brings in the registry PATH (Windows)" { if (builtin.os.tag != .windows) return error.SkipZigTest; var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("PATH", "C:\\zz-session-only"); fres.applyFres(allo, &mapz); const pathz = mapz.get("PATH").?; try tszz.expect(std.ascii.findIgnoreCase(pathz, "C:\\zz-session-only") != null); try tszz.expect(std.ascii.findIgnoreCase(pathz, "system32") != null); }
test "mergApply: volatile wins over machine and user for a name they set (USERNAME), is ignored for any other name" { if (builtin.os.tag != .windows) return error.SkipZigTest; var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("USERNAME", "Admin"); try mapz.put("USERPROFILE", "/iso"); const mach = [_]Pair{.{ .name = "USERNAME", .valu = "SYSTEM" }}; const vola = [_]Pair{ .{ .name = "UserName", .valu = "Admin" }, .{ .name = "USERPROFILE", .valu = "/real" } }; try fres.mergApply(allo, &mapz, &mach, &.{}, &vola); try tszz.expectEqualStrings("Admin", mapz.get("USERNAME").?); try tszz.expectEqualStrings("/iso", mapz.get("USERPROFILE").?); }
test "mergApply never sets an empty value and never takes PATH from the volatile list" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); var mapz: Map = .init(allo); try mapz.put("PATH", "/keep"); const user = [_]Pair{ .{ .name = "EMPTY_ONE", .valu = "" }, .{ .name = "PATH", .valu = "/u" } }; const vola = [_]Pair{.{ .name = "PATH", .valu = "/vol" }}; try fres.mergApply(allo, &mapz, &.{}, &user, &vola); try tszz.expect(mapz.get("EMPTY_ONE") == null); try tszz.expect(std.mem.indexOf(u8, mapz.get("PATH").?, "/vol") == null); try tszz.expect(std.mem.indexOf(u8, mapz.get("PATH").?, "/u") != null); }
